mapper.select:
SELECT id, name, phone, owner
FROM clue
WHERE organization_id = #{orgId}
  AND in_shared_pool = 0

    AND owner IN

        #{ownerId}


  AND (name LIKE CONCAT('%', #{keyword}, '%')
       OR phone LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY create_time DESC
LIMIT #{limit}

SELECT c.id, c.name, c.owner, MIN(cc.phone) AS phone FROM customer c LEFT JOIN customer_contact cc ON c.id = cc.customer_id WHERE c.organization_id = #{orgId} AND c.in_shared_pool = 0
AND c.owner IN
#{ownerId}
AND (c.name LIKE CONCAT('%', #{keyword}, '%') OR cc.phone LIKE CONCAT('%', #{keyword}, '%')) GROUP BY c.id, c.name, c.owner ORDER BY c.create_time DESC LIMIT #{limit}

SELECT o.id, o.name, c.name AS customerName, o.amount, o.stage
FROM opportunity o
LEFT JOIN customer c ON o.customer_id = c.id
WHERE o.organization_id = #{orgId}

    AND o.owner IN

        #{ownerId}


  AND (o.name LIKE CONCAT('%', #{keyword}, '%')
       OR c.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY o.create_time DESC
LIMIT #{limit}

SELECT ct.id, ct.name, c.name AS customerName, ct.amount, ct.status
FROM crm_contract ct
LEFT JOIN customer c ON ct.customer_id = c.id
WHERE ct.organization_id = #{orgId}

    AND ct.owner IN

        #{ownerId}


  AND (ct.name LIKE CONCAT('%', #{keyword}, '%')
       OR c.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY ct.create_time DESC
LIMIT #{limit}
